(function(){const a=()=>matchMedia("(max-width: 720px)").matches;if(!document.body.classList.contains("route-studio"))return;const n=[...document.querySelectorAll(".studio-tab[data-section]")],r={studio:["#top",".hero",".about"],work:["#work"],packages:["#packages"],contact:["#studio-contact",".studio-finale"]};function s(t){n.forEach(e=>{const o=e.dataset.section===t;e.classList.toggle("is-active",o),o?e.setAttribute("aria-current","page"):e.removeAttribute("aria-current")})}function c(){if(!a())return;activeSection();let t="studio";const e=scrollY+innerHeight*.38;for(const[o,d]of Object.entries(r))for(const l of d){const i=document.querySelector(l);i&&i.offsetTop<=e&&(t=o)}s(t)}const u=document.getElementById("menu-btn");document.querySelector(".studio-tab--menu")?.addEventListener("click",t=>{t.preventDefault(),u?.click()}),n.forEach(t=>{t.addEventListener("click",()=>{t.dataset.section&&s(t.dataset.section)})}),addEventListener("scroll",c,{passive:!0}),addEventListener("hashchange",c,{passive:!0}),c()})();
